import type { AnalysisResponse, ExperimentSet, ExperimentSetInfo, IncidentRecord, IncidentSummary } from "./types";

/**
 * Demo mode data lives in /public/demo/*.json and is generated by scripts/export_demo_fixtures.py from the
 * REAL saved experiment outputs and from the synthetic demo model. Everything loaded here is labelled
 * "DEMO FIXTURE" in the UI. It is never used as a fallback for a failed live request.
 */
export interface DemoFixture { name: string; description: string; analysis: AnalysisResponse }
export interface DemoBundle {
  generated_utc: string;
  note: string;
  analyses: DemoFixture[];
  experiments: { sets: ExperimentSetInfo[]; data: Record<string, ExperimentSet> };
  incidents: (IncidentSummary & { record: IncidentRecord })[];
}

let cache: Promise<DemoBundle> | null = null;
export function loadDemo(): Promise<DemoBundle> {
  cache ??= fetch(`${import.meta.env.BASE_URL}demo/demo-bundle.json`).then((r) => {
    if (!r.ok) throw new Error("Demo fixtures are missing from this build (run scripts/export_demo_fixtures.py).");
    return r.json();
  });
  cache.catch(() => { cache = null; });
  return cache;
}
